/*****************************************************************************
* ---- SECURITY -- SECURITY control and status registers ----
* 0x4300 - 0x432A
*   Control and status registers for the security and encryption moduleAll registers are only writable when in system mode
*****************************************************************************/
#define DATA_SECURITY_BASE            (0x4300u)
#define DATA_SECURITY_END             (0x432Au)
#define DATA_SECURITY_TOP             ((DATA_SECURITY_END | 1) + 1)
#define DATA_SECURITY_SIZE            (DATA_SECURITY_TOP - DATA_SECURITY_BASE)

/** SECURITY_CONFIG - RW - Security configuration register **/
#define SECURITY_CONFIG               (kReg[(0x4300u - DATA_CHIP_BASE) / 2])
#define SECURITY_CONFIG_REG           (kReg[(0x4300u - DATA_CHIP_BASE) / 2])
#define SECURITY_CONFIG_ADDR          (0x4300u)
#define SECURITY_CONFIG_RESET         (0x0000u)
// Starts AES engine for one cycle, auto clears - RW [0:0]
# define SECURITY_CONFIG_START_AES                           (0x0001u)
# define SECURITY_CONFIG_START_AES_MASK                      (0x0001u)
# define SECURITY_CONFIG_START_AES_BIT                       (0)
# define SECURITY_CONFIG_START_AES_BITS                      (1)
// Stop clock until Plaintext writes have occured - RW [1:1]
# define SECURITY_CONFIG_WAIT_PT_WRITE                       (0x0002u)
# define SECURITY_CONFIG_WAIT_PT_WRITE_MASK                  (0x0002u)
# define SECURITY_CONFIG_WAIT_PT_WRITE_BIT                   (1)
# define SECURITY_CONFIG_WAIT_PT_WRITE_BITS                  (1)
// When Ciphertext is ready, stop clock until reads occur - RW [2:2]
# define SECURITY_CONFIG_WAIT_CT_READ                        (0x0004u)
# define SECURITY_CONFIG_WAIT_CT_READ_MASK                   (0x0004u)
# define SECURITY_CONFIG_WAIT_CT_READ_BIT                    (2)
# define SECURITY_CONFIG_WAIT_CT_READ_BITS                   (1)
// Ciphertext copied to CBC_STATE registers at output - RW [3:3]
# define SECURITY_CONFIG_CT_TO_CBC_ST                        (0x0008u)
# define SECURITY_CONFIG_CT_TO_CBC_ST_MASK                   (0x0008u)
# define SECURITY_CONFIG_CT_TO_CBC_ST_BIT                    (3)
# define SECURITY_CONFIG_CT_TO_CBC_ST_BITS                   (1)
// XOR incoming plaintext on writes with saved CBC_STATE - RW [4:4]
# define SECURITY_CONFIG_CBC_XOR_PT                          (0x0010u)
# define SECURITY_CONFIG_CBC_XOR_PT_MASK                     (0x0010u)
# define SECURITY_CONFIG_CBC_XOR_PT_BIT                      (4)
# define SECURITY_CONFIG_CBC_XOR_PT_BITS                     (1)
// CT output it is XORed with stored CBC_STATE to generate final MIC in CCM - RW [5:5]
# define SECURITY_CONFIG_MIC_XOR_CT                          (0x0020u)
# define SECURITY_CONFIG_MIC_XOR_CT_MASK                     (0x0020u)
# define SECURITY_CONFIG_MIC_XOR_CT_BIT                      (5)
# define SECURITY_CONFIG_MIC_XOR_CT_BITS                     (1)
// Input Plaintext is taken from CBC_STATE register incremented by one - RW [6:6]
# define SECURITY_CONFIG_CTR_IN                              (0x0040u)
# define SECURITY_CONFIG_CTR_IN_MASK                         (0x0040u)
# define SECURITY_CONFIG_CTR_IN_BIT                          (6)
# define SECURITY_CONFIG_CTR_IN_BITS                         (1)
// Security module reset - RW [7:7]
# define SECURITY_CONFIG_SEC_RST                             (0x0080u)
# define SECURITY_CONFIG_SEC_RST_MASK                        (0x0080u)
# define SECURITY_CONFIG_SEC_RST_BIT                         (7)
# define SECURITY_CONFIG_SEC_RST_BITS                        (1)

