#define MAC_RX_INT_SRC_REG            (kReg[(0x4604u - DATA_CHIP_BASE) / 2])
#define MAC_RX_INT_SRC_ADDR           (0x4604u)
#define MAC_RX_INT_SRC_RESET          (0x0000u)
// Receive packet complete - RW [0:0]
# define MAC_RX_INT_SRC_RX_COMPLETE_SRC                      (0x0001u)
# define MAC_RX_INT_SRC_RX_COMPLETE_SRC_MASK                 (0x0001u)
# define MAC_RX_INT_SRC_RX_COMPLETE_SRC_BIT                  (0)
# define MAC_RX_INT_SRC_RX_COMPLETE_SRC_BITS                 (1)
// ACK transmitted after receive packet that requested TX ACK - RW [1:1]
# define MAC_RX_INT_SRC_TX_ACK_SRC                           (0x0002u)
# define MAC_RX_INT_SRC_TX_ACK_SRC_MASK                      (0x0002u)
# define MAC_RX_INT_SRC_TX_ACK_SRC_BIT                       (1)
# define MAC_RX_INT_SRC_TX_ACK_SRC_BITS                      (1)
// Receive activity, 1 : after SFD received till end of packet - RW [2:2]
# define MAC_RX_INT_SRC_RX_FRAME_SRC                         (0x0004u)
# define MAC_RX_INT_SRC_RX_FRAME_SRC_MASK                    (0x0004u)
# define MAC_RX_INT_SRC_RX_FRAME_SRC_BIT                     (2)
# define MAC_RX_INT_SRC_RX_FRAME_SRC_BITS                    (1)
// All fields used for filtering have been received and pass filtering - RW [3:3]
# define MAC_RX_INT_SRC_RX_FILT_COMP_SRC                     (0x0008u)
# define MAC_RX_INT_SRC_RX_FILT_COMP_SRC_MASK                (0x0008u)
# define MAC_RX_INT_SRC_RX_FILT_COMP_SRC_BIT                 (3)
# define MAC_RX_INT_SRC_RX_FILT_COMP_SRC_BITS                (1)
// All address fields have been received and pass filtering - RW [4:4]
# define MAC_RX_INT_SRC_RX_ADDR_REC_COMP_SRC                 (0x0010u)
# define MAC_RX_INT_SRC_RX_ADDR_REC_COMP_SRC_MASK            (0x0010u)
# define MAC_RX_INT_SRC_RX_ADDR_REC_COMP_SRC_BIT             (4)
# define MAC_RX_INT_SRC_RX_ADDR_REC_COMP_SRC_BITS            (1)
// Baseband receiver error, packet stops prematurely - RW [5:5]
# define MAC_RX_INT_SRC_RX_ERROR_SRC                         (0x0020u)
# define MAC_RX_INT_SRC_RX_ERROR_SRC_MASK                    (0x0020u)
# define MAC_RX_INT_SRC_RX_ERROR_SRC_BIT                     (5)
# define MAC_RX_INT_SRC_RX_ERROR_SRC_BITS                    (1)
// BB filters length of 0 or greater than 127 - RW [6:6]
# define MAC_RX_INT_SRC_BB_RX_LEN_ERR_SRC                    (0x0040u)
# define MAC_RX_INT_SRC_BB_RX_LEN_ERR_SRC_MASK               (0x0040u)
# define MAC_RX_INT_SRC_BB_RX_LEN_ERR_SRC_BIT                (6)
# define MAC_RX_INT_SRC_BB_RX_LEN_ERR_SRC_BITS               (1)
// Receive overflow, no buffers available when data is available to DMA to RAM - RW [7:7]
# define MAC_RX_INT_SRC_RX_OVFLW_SRC                         (0x0080u)
# define MAC_RX_INT_SRC_RX_OVFLW_SRC_MASK                    (0x0080u)
# define MAC_RX_INT_SRC_RX_OVFLW_SRC_BIT                     (7)
# define MAC_RX_INT_SRC_RX_OVFLW_SRC_BITS                    (1)
// Error when attempting to send TX ACK. - RW [8:8]
# define MAC_RX_INT_SRC_TX_ACK_ERR_SRC                       (0x0100u)
# define MAC_RX_INT_SRC_TX_ACK_ERR_SRC_MASK                  (0x0100u)
# define MAC_RX_INT_SRC_TX_ACK_ERR_SRC_BIT                   (8)
# define MAC_RX_INT_SRC_TX_ACK_ERR_SRC_BITS                  (1)
// Transmit stopped a packet being received - RW [9:9]
# define MAC_RX_INT_SRC_TX_COLL_RX_SRC                       (0x0200u)
# define MAC_RX_INT_SRC_TX_COLL_RX_SRC_MASK                  (0x0200u)
# define MAC_RX_INT_SRC_TX_COLL_RX_SRC_BIT                   (9)
# define MAC_RX_INT_SRC_TX_COLL_RX_SRC_BITS                  (1)
// DMA buffer rollback, only possible in promiscuous mode - RW [10:10]
# define MAC_RX_INT_SRC_RX_ROLLBACK_SRC                      (0x0400u)
# define MAC_RX_INT_SRC_RX_ROLLBACK_SRC_MASK                 (0x0400u)
# define MAC_RX_INT_SRC_RX_ROLLBACK_SRC_BIT                  (10)
# define MAC_RX_INT_SRC_RX_ROLLBACK_SRC_BITS                 (1)
// Buffer A unloaded, full or RX_COMPLETE - RW [11:11]
# define MAC_RX_INT_SRC_RX_A_UNLOAD_SRC                      (0x0800u)
# define MAC_RX_INT_SRC_RX_A_UNLOAD_SRC_MASK                 (0x0800u)
# define MAC_RX_INT_SRC_RX_A_UNLOAD_SRC_BIT                  (11)
# define MAC_RX_INT_SRC_RX_A_UNLOAD_SRC_BITS                 (1)
// Buffer B unloaded, full or RX_COMPLETE - RW [12:12]
# define MAC_RX_INT_SRC_RX_B_UNLOAD_SRC                      (0x1000u)
# define MAC_RX_INT_SRC_RX_B_UNLOAD_SRC_MASK                 (0x1000u)
# define MAC_RX_INT_SRC_RX_B_UNLOAD_SRC_BIT                  (12)
# define MAC_RX_INT_SRC_RX_B_UNLOAD_SRC_BITS                 (1)

/** MAC_TX_INT_SRC - RW - MAC transmitter interrupt source **/
#define MAC_TX_INT_SRC                (kReg[(0x4606u - DATA_CHIP_BASE) / 2])
#define MAC_TX_INT_SRC_REG            (kReg[(0x4606u - DATA_CHIP_BASE) / 2])
#define MAC_TX_INT_SRC_ADDR           (0x4606u)
#define MAC_TX_INT_SRC_RESET          (0x0000u)
// Transmit complete, all transmit buffers unload at transmit complete - RW [0:0]
# define MAC_TX_INT_SRC_TX_COMPLETE_SRC                      (0x0001u)
# define MAC_TX_INT_SRC_TX_COMPLETE_SRC_MASK                 (0x0001u)
# define MAC_TX_INT_SRC_TX_COMPLETE_SRC_BIT                  (0)
# define MAC_TX_INT_SRC_TX_COMPLETE_SRC_BITS                 (1)
// Received ACK requested from transmit correctly - RW [1:1]
# define MAC_TX_INT_SRC_RX_ACK_SRC                           (0x0002u)
# define MAC_TX_INT_SRC_RX_ACK_SRC_MASK                      (0x0002u)
# define MAC_TX_INT_SRC_RX_ACK_SRC_BIT                       (1)
# define MAC_TX_INT_SRC_RX_ACK_SRC_BITS                      (1)
// Backoff complete. - RW [2:2]
# define MAC_TX_INT_SRC_BO_COMPLETE_SRC                      (0x0004u)
# define MAC_TX_INT_SRC_BO_COMPLETE_SRC_MASK                 (0x0004u)
# define MAC_TX_INT_SRC_BO_COMPLETE_SRC_BIT                  (2)
# define MAC_TX_INT_SRC_BO_COMPLETE_SRC_BITS                 (1)
// SFD sent - RW [3:3]
# define MAC_TX_INT_SRC_SFD_SENT_SRC                         (0x0008u)
# define MAC_TX_INT_SRC_SFD_SENT_SRC_MASK                    (0x0008u)
# define MAC_TX_INT_SRC_SFD_SENT_SRC_BIT                     (3)
# define MAC_TX_INT_SRC_SFD_SENT_SRC_BITS                    (1)
// Channel busy when checked, transmit aborted - RW [4:4]
# define MAC_TX_INT_SRC_CCA_FAIL_SRC                         (0x0010u)
# define MAC_TX_INT_SRC_CCA_FAIL_SRC_MASK                    (0x0010u)
# define MAC_TX_INT_SRC_CCA_FAIL_SRC_BIT                     (4)
# define MAC_TX_INT_SRC_CCA_FAIL_SRC_BITS                    (1)
// Transmit buffer underflow - RW [5:5]
# define MAC_TX_INT_SRC_TX_UNDERFLOW_SRC                     (0x0020u)
# define MAC_TX_INT_SRC_TX_UNDERFLOW_SRC_MASK                (0x0020u)
# define MAC_TX_INT_SRC_TX_UNDERFLOW_SRC_BIT                 (5)
# define MAC_TX_INT_SRC_TX_UNDERFLOW_SRC_BITS                (1)
// Transmit lock failed - RW [6:6]
# define MAC_TX_INT_SRC_TX_LOCK_FAIL_SRC                     (0x0040u)
# define MAC_TX_INT_SRC_TX_LOCK_FAIL_SRC_MASK                (0x0040u)
# define MAC_TX_INT_SRC_TX_LOCK_FAIL_SRC_BIT                 (6)
# define MAC_TX_INT_SRC_TX_LOCK_FAIL_SRC_BITS                (1)
// Receive ACK not received or started by timeout - RW [7:7]
# define MAC_TX_INT_SRC_ACK_EXPIRED_SRC                      (0x0080u)
# define MAC_TX_INT_SRC_ACK_EXPIRED_SRC_MASK                 (0x0080u)
# define MAC_TX_INT_SRC_ACK_EXPIRED_SRC_BIT                  (7)
# define MAC_TX_INT_SRC_ACK_EXPIRED_SRC_BITS                 (1)
// Buffer A unloaded - RW [8:8]
# define MAC_TX_INT_SRC_TX_A_UNLOAD_SRC                      (0x0100u)
# define MAC_TX_INT_SRC_TX_A_UNLOAD_SRC_MASK                 (0x0100u)
# define MAC_TX_INT_SRC_TX_A_UNLOAD_SRC_BIT                  (8)
# define MAC_TX_INT_SRC_TX_A_UNLOAD_SRC_BITS                 (1)
// Buffer B unloaded - RW [9:9]
# define MAC_TX_INT_SRC_TX_B_UNLOAD_SRC                      (0x0200u)
# define MAC_TX_INT_SRC_TX_B_UNLOAD_SRC_MASK                 (0x0200u)
# define MAC_TX_INT_SRC_TX_B_UNLOAD_SRC_BIT                  (9)
# define MAC_TX_INT_SRC_TX_B_UNLOAD_SRC_BITS                 (1)

/** MAC_TIMER_INT_SRC - RW - MAC timer interrut source **/
