# define EMU_CTRL_VCO_AMP_H_DR_MASK                          (0x0008u)
# define EMU_CTRL_VCO_AMP_H_DR_BIT                           (3)
# define EMU_CTRL_VCO_AMP_H_DR_BITS                          (1)
// krakatoa OSC24M_LO - RW [4:4]
# define EMU_CTRL_OSC24M_LO_DR                               (0x0010u)
# define EMU_CTRL_OSC24M_LO_DR_MASK                          (0x0010u)
# define EMU_CTRL_OSC24M_LO_DR_BIT                           (4)
# define EMU_CTRL_OSC24M_LO_DR_BITS                          (1)
// krakatoa OSC24M_HI - RW [5:5]
# define EMU_CTRL_OSC24M_HI_DR                               (0x0020u)
# define EMU_CTRL_OSC24M_HI_DR_MASK                          (0x0020u)
# define EMU_CTRL_OSC24M_HI_DR_BIT                           (5)
# define EMU_CTRL_OSC24M_HI_DR_BITS                          (1)

/** EMU_PRESCALE_CTRL - RW - Receiver ADC mux control **/
#define EMU_PRESCALE_CTRL             (kReg[(0x6016u - DATA_CHIP_BASE) / 2])
#define EMU_PRESCALE_CTRL_REG         (kReg[(0x6016u - DATA_CHIP_BASE) / 2])
#define EMU_PRESCALE_CTRL_ADDR        (0x6016u)
#define EMU_PRESCALE_CTRL_RESET       (0x0000u)
// 3 bit code Remaping enabled - RW [0:0]
# define EMU_PRESCALE_CTRL_PRE_REMAP                         (0x0001u)
# define EMU_PRESCALE_CTRL_PRE_REMAP_MASK                    (0x0001u)
# define EMU_PRESCALE_CTRL_PRE_REMAP_BIT                     (0)
# define EMU_PRESCALE_CTRL_PRE_REMAP_BITS                    (1)

/*****************************************************************************
* ---- RAM -- Data RAM ----
* 0x6C00 - 0x7FFF
*   word only accessible RAMRetains data when in deep sleep mode
*****************************************************************************/
#define DATA_RAM_BASE                 (0x6C00u)
#define DATA_RAM_END                  (0x7FFFu)
#define DATA_RAM_TOP                  ((DATA_RAM_END | 1) + 1)
#define DATA_RAM_SIZE                 (DATA_RAM_TOP - DATA_RAM_BASE)

/*****************************************************************************
* ---- RAMBYTES -- Data RAM ----
* 0xEC00 - 0xFFFF
*   byte only accessible RAMRetains data when in deep sleep mode
*****************************************************************************/
#define DATA_RAMBYTES_BASE            (0xEC00u)
#define DATA_RAMBYTES_END             (0xFFFFu)
#define DATA_RAMBYTES_TOP             ((DATA_RAMBYTES_END | 1) + 1)
#define DATA_RAMBYTES_SIZE            (DATA_RAMBYTES_TOP - DATA_RAMBYTES_BASE)

#if 0 // For some reason xapncc seems to think kReg itself is volatile!
extern volatile unsigned short kReg[];  /* Register "array" at DATA_CHIP_BASE */
#else // The below technique yields more efficient code for &= and |= ops
typedef struct {
  volatile unsigned short kRegs[(DATA_RAM_BASE - DATA_CHIP_BASE) / 2];
} kRegs_t;
extern kRegs_t Regs;    /* Regs and kReg synonyms in cstartup */
#define kReg Regs.kRegs   /* Emulate kReg array */
#endif

